/**
 * One criterion's coverage — a kind of its own, NESTED (the §4.4 law).
 *
 * A gate reports many of these, and a repeated nested structure inside a kind
 * is minted rather than smeared across the parent: a reviewer surface renders
 * a self-describing row without knowing what produced it, and a single
 * criterion can travel an edge as a value in its own right.
 *  *
 *  * Kind `criterion_coverage` (registry v2).
 */
export interface CriterionCoverage {
  /**
   * Human-readable name of the criterion, from its definition.
   */
  label: string;
  /**
   * The registered kind this payload is an instance of.
   */
  __kind?: "criterion_coverage";
  /**
   * The accepted verdict for this criterion: 'met', 'not_met', 'unknown', or 'not_applicable'.
   */
  verdict: "met" | "not_met" | "unknown" | "not_applicable";
  /**
   * Whether this criterion was declared blocking (required) in the gate config.
   */
  required: boolean;
  /**
   * The evaluator's explanation of why this verdict was reached.
   */
  rationale: string;
  /**
   * The accepted assessment's confidence, 0.0 to 1.0.
   */
  confidence: number;
  /**
   * Id of the declared criterion this row covers.
   */
  criterion_id: string;
  /**
   * Id of the evaluator whose assessment was accepted for this criterion.
   */
  evaluator_id: string;
  /**
   * Evidence ids the accepted assessment cited for this verdict.
   */
  evidence_refs: string[];
}

